  CREATE TABLE "EBA_SALES_LINKS" 
   (	"ID" NUMBER, 
	"ROW_VERSION_NUMBER" NUMBER NOT NULL ENABLE, 
	"DEAL_ID" NUMBER, 
	"LINK_TARGET" VARCHAR2(4000) NOT NULL ENABLE, 
	"LINK_TEXT" VARCHAR2(255) NOT NULL ENABLE, 
