 after insert or update on  EBA_SALES_CUSTOMERS
 FOR EACH ROW
  BEGIN
  INSERT
  INTO XXEBA_SALES_CUSTOMERS_HIST
    (   
ID,	                           
ROW_VERSION_NUMBER,	           
ROW_KEY,	                       
CUSTOMER_NAME,	               
TAGS,	                       
DEFAULT_REP_ID,	               
CUSTOMER_SIC,	               
CUSTOMER_DUNS,	               
CUSTOMER_WEB_SITE,	           
CUSTOMER_STOCK_SYMB,	           
CUSTOMER_NUMBER_OF_EMP,	       
CUSTOMER_IS_PUBLIC_COMP_YN,    
CUSTOMER_FACEBOOK,	           
CUSTOMER_LINKEDIN,	           
CUSTOMER_TWITTER,	           
CUSTOMER_DESCRIPTION,	       
CUSTOMER_TERRITORY_ID,	       
CUSTOMER_IS_KEY_ACCOUNT_YN,   
CREATED_BY,	                   
CREATED,	                       
UPDATED_BY,	                   
UPDATED,	                       
ACCOUNT_SOURCE,	               
GST_NO,	                       
INDUSTRY_ID,	                   
CLASSIFICATION_ID,	           
PAN_NUMBER,	                   
PHONE_NUMBER,	               
MOBILE_NUMBER,	               
EMAIL_ADDRESS,	               
CUSTOMER_CODE,	               
