    )
    VALUES
    (
:new.ID,	                           
:new.ROW_VERSION_NUMBER,	           
:new.ROW_KEY,	                       
:new.CUSTOMER_NAME,	               
:new.TAGS,	                       
:new.DEFAULT_REP_ID,	               
:new.CUSTOMER_SIC,	               
:new.CUSTOMER_DUNS,	               
:new.CUSTOMER_WEB_SITE,	           
:new.CUSTOMER_STOCK_SYMB,	           
:new.CUSTOMER_NUMBER_OF_EMP,	       
:new.CUSTOMER_IS_PUBLIC_COMP_YN,    
:new.CUSTOMER_FACEBOOK,	           
:new.CUSTOMER_LINKEDIN,	           
:new.CUSTOMER_TWITTER,	           
:new.CUSTOMER_DESCRIPTION,	       
:new.CUSTOMER_TERRITORY_ID,	       
:new.CUSTOMER_IS_KEY_ACCOUNT_YN,   
:new.CREATED_BY,	                   
:new.CREATED,	                       
:new.UPDATED_BY,	                   
:new.UPDATED,	                       
:new.ACCOUNT_SOURCE,	               
:new.GST_NO,	                       
:new.INDUSTRY_ID,	                   
:new.CLASSIFICATION_ID,	           
:new.PAN_NUMBER,	                   
:new.PHONE_NUMBER,	               
:new.MOBILE_NUMBER,	               
:new.EMAIL_ADDRESS,	               
:new.CUSTOMER_CODE,	               
:new.LAST_UPDATED_LATITUDE,	       
:new.LAST_UPDATED_LONGITUDE,	       
:new.STATUS,	                       
:new.VERIFIED_ON,
:new.VERIFIED_BY,
:new.VERIFY_COMMENTS,
:new.TEAM_LEAD_COMMENTS,
:new.TEAM_LEAD_ID 
    );
END;




