  CREATE OR REPLACE EDITIONABLE TRIGGER "TRG_EBA_SALES_PRODUCTS_DEL_HIST" 
BEFORE DELETE ON EBA_SALES_PRODUCTS
FOR EACH ROW
BEGIN
    INSERT INTO EBA_SALES_PRODUCTS_DEL_HIST
    (
        HIST_ID,PRODUCT_ID, ROW_KEY, PRODUCT_NAME, PRODUCT_DESCRIPTION,
        PRODUCT_FAMILY_ID, PRODUCT_SKU, PRODUCT_PRICE, PRODUCT_TYPE_ID,
        CURRENCY_TYPE, CATALOGUE_NO, ATT_MIMETYPE, ATT_FILENAME,
        PRODUCT_COST, PRODUCT_CURRENCY_TYPE, BRAND_ID, UNIT_OF_MEASURE,
        LEAD_TIME, MINIMUM_ORDER_QUANTITY, DURATION_TYPE,
        STOCK_ID, STATUS, PRODUCT_GROUP, LOCATION,
        DELETED_BY, DELETED_ON
    )
    VALUES
    (
        EBA_SALES_PRODUCTS_DEL_HIST_SEQ.NEXTVAL,:OLD.ID, :OLD.ROW_KEY, :OLD.PRODUCT_NAME, :OLD.PRODUCT_DESCRIPTION,
        :OLD.PRODUCT_FAMILY_ID, :OLD.PRODUCT_SKU, :OLD.PRODUCT_PRICE, :OLD.PRODUCT_TYPE_ID,
        :OLD.CURRENCY_TYPE, :OLD.CATALOGUE_NO, :OLD.ATT_MIMETYPE, :OLD.ATT_FILENAME,
        :OLD.PRODUCT_COST, :OLD.PRODUCT_CURRENCY_TYPE, :OLD.BRAND_ID, :OLD.UNIT_OF_MEASURE,
        :OLD.LEAD_TIME, :OLD.MINIMUM_ORDER_QUANTITY, :OLD.DURATION_TYPE,
        :OLD.STOCK_ID, :OLD.STATUS, :OLD.PRODUCT_GROUP, :OLD.LOCATION,
        NVL(apex_application.g_user, USER), LOCALTIMESTAMP
    );
END;
