  CREATE OR REPLACE EDITIONABLE TRIGGER "BIU_EBA_SALES_APPOINTMENT" 
   before insert or update on XXEBA_SALES_APPOINTMENT
   for each row
begin
   if :new.Appointment_ID   is null then
     select to_number(sys_guid(),'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX') into :new.Appointment_ID  from dual;
   end if;
   if inserting then
       :new.created := localtimestamp;
       :new.created_by := nvl(wwv_flow.g_user,user);
       :new.updated := localtimestamp;
       :new.updated_by := nvl(wwv_flow.g_user,user);
       :new.row_version_number := 1;
        if :new.APPOINTMENT_STATUS   is null then
           :new.APPOINTMENT_STATUS :='Scheduled';
       end if;
   elsif updating then
       :new.row_version_number := nvl(:old.row_version_number,1) + 1;
   end if;
   if inserting or updating then
       :new.updated := localtimestamp;
       :new.updated_by := nvl(wwv_flow.g_user,user);
   end if;
end;





